"""Module containing the functions to write the human readable files of a provenance RO-Crate:
the HTML preview (ro-crate-preview.html) and the README.md of the workflow crates."""
import hashlib
import json
from html import escape
from pathlib import Path
from typing import Any, Union

from biobb_common.provenance.crate import as_list
from biobb_common.provenance.graph import read_graph, to_mermaid

PREVIEW = "ro-crate-preview.html"
README = "README.md"
# First line of the generated files, existing files without it are never overwritten
GENERATED_MARK = "<!-- Generated by biobb_common provenance -->"
MERMAID_JS = "https://cdn.jsdelivr.net/npm/mermaid@11.4.1/dist/mermaid.esm.min.mjs"
STYLE = """
body { font-family: system-ui, sans-serif; max-width: 70rem; margin: 2rem auto; padding: 0 1rem; color: #1f2937; }
table { border-collapse: collapse; margin-bottom: 1.5rem; display: block; overflow-x: auto; }
th, td { border: 1px solid #d1d5db; padding: .35rem .6rem; text-align: left; vertical-align: top; }
th { background: #f3f4f6; }
code, .id { font-family: ui-monospace, monospace; font-size: .9em; overflow-wrap: anywhere; }
.failed { color: #b91c1c; font-weight: bold; }
details { margin-bottom: .5rem; }
summary { cursor: pointer; }
"""


def is_generated(path: Path) -> bool:
    """Return True if **path** does not exist or was written by these functions."""
    if not path.exists():
        return True
    with open(path, encoding="utf-8", errors="replace") as file:
        return file.readline().strip() == GENERATED_MARK


def write_preview(crate_dir: Union[str, Path]) -> Path:
    """Write the ro-crate-preview.html of an RO-Crate: crate metadata, graph,
    steps and all the entities of the ro-crate-metadata.json file.

    Args:
        crate_dir (str, Path): Directory containing the ro-crate-metadata.json file.

    Returns:
        Path: Path to the written ro-crate-preview.html file.
    """
    crate_dir = Path(crate_dir)
    entities = _entities(crate_dir)
    root = entities["./"]
    html = [
        GENERATED_MARK,
        "<!DOCTYPE html>",
        '<html lang="en"><head><meta charset="utf-8">',
        '<meta name="viewport" content="width=device-width, initial-scale=1">',
        f"<title>{escape(str(root.get('name', 'RO-Crate')))}</title>",
        f"<style>{STYLE}</style>",
        "</head><body>",
        f"<h1>{escape(str(root.get('name', 'RO-Crate')))}</h1>",
        f"<p>{escape(str(root.get('description', '')))}</p>",
        "<table>",
    ]
    for key in ("author", "publisher", "license", "conformsTo", "datePublished", "mainEntity"):
        if key in root:
            html.append(f"<tr><th>{key}</th><td>{_value(root[key], entities)}</td></tr>")
    html.append("</table>")

    html.append("<h2>Graph</h2>")
    html.append(f'<pre class="mermaid">{escape(to_mermaid(read_graph(crate_dir)))}</pre>')
    html.append(f'<script type="module">import mermaid from "{MERMAID_JS}"; mermaid.initialize({{startOnLoad: true}});</script>')

    html.append("<h2>Executions</h2>")
    html.append("<table><tr><th>Name</th><th>Status</th><th>Start</th><th>End</th><th>Software</th></tr>")
    for action in _actions(entities):
        failed = "Failed" in action.get("actionStatus", "")
        html.append(
            f'<tr><td><a href="#{_anchor(action["@id"])}">{escape(action.get("name", action["@id"]))}</a></td>'
            f'<td class="{"failed" if failed else ""}">{"Failed" if failed else "Completed"}</td>'
            f"<td>{escape(action.get('startTime', ''))}</td><td>{escape(action.get('endTime', ''))}</td>"
            f"<td>{escape(_software(action, entities))}</td></tr>"
        )
    html.append("</table>")

    html.append("<h2>Entities</h2>")
    for entity in entities.values():
        types = ", ".join(as_list(entity.get("@type")))
        html.append(f'<details id="{_anchor(entity["@id"])}"><summary><span class="id">{escape(entity["@id"])}</span> ({escape(types)})</summary><table>')
        for key, value in entity.items():
            if key not in ("@id", "@type"):
                html.append(f"<tr><th>{escape(key)}</th><td>{_value(value, entities)}</td></tr>")
        html.append("</table></details>")
    html.append("</body></html>")

    preview_path = crate_dir / PREVIEW
    preview_path.write_text("\n".join(html) + "\n", encoding="utf-8")
    return preview_path


def write_readme(crate_dir: Union[str, Path]) -> Path:
    """Write the README.md of a workflow RO-Crate: description, steps, inputs,
    outputs and the Mermaid graph (rendered by GitHub and GitLab).

    Args:
        crate_dir (str, Path): Directory containing the ro-crate-metadata.json file.

    Returns:
        Path: Path to the written README.md file.
    """
    crate_dir = Path(crate_dir)
    entities = _entities(crate_dir)
    root = entities["./"]
    run = entities.get("#workflow-run", {})
    lines = [
        GENERATED_MARK,
        f"# {root.get('name', 'Workflow')}",
        "",
        str(root.get("description", "")),
        "",
        "Provenance [RO-Crate](https://www.researchobject.org/ro-crate/) of a [BioBB](https://mmb.irbbarcelona.org/biobb/) workflow "
        "execution, described in `ro-crate-metadata.json` and previewed in `ro-crate-preview.html`.",
        "",
    ]
    if run:
        status = "failed" if "Failed" in run.get("actionStatus", "") else "completed"
        lines += [f"- Status: {status}", f"- Start: {run.get('startTime', '')}", f"- End: {run.get('endTime', '')}"]
    if "author" in root:
        lines.append("- Author: " + ", ".join(entities.get(a["@id"], a).get("name", a["@id"]) for a in as_list(root["author"])))
    lines += ["", "## Steps", "", "| # | Building block | Status | Start | End |", "|---|---|---|---|---|"]
    for position, action in enumerate((a for a in _actions(entities) if a["@id"] != "#workflow-run"), start=1):
        status = "failed" if "Failed" in action.get("actionStatus", "") else "completed"
        block = entities.get(action["instrument"]["@id"], {}).get("name", action["instrument"]["@id"])
        lines.append(f"| {position} | {block} | {status} | {action.get('startTime', '')} | {action.get('endTime', '')} |")
    for title, key in (("Inputs", "object"), ("Outputs", "result")):
        lines += ["", f"## {title}", ""]
        lines += [f"- `{ref['@id']}`" for ref in as_list(run.get(key))] or ["None"]
    lines += ["", "## Graph", "", "```mermaid", to_mermaid(read_graph(crate_dir)).rstrip(), "```", ""]

    readme_path = crate_dir / README
    readme_path.write_text("\n".join(lines), encoding="utf-8")
    return readme_path


def _entities(crate_dir: Path) -> dict[str, dict]:
    return {e["@id"]: e for e in json.loads((crate_dir / "ro-crate-metadata.json").read_text())["@graph"]}


def _actions(entities: dict[str, dict]) -> list[dict]:
    actions = [e for e in entities.values() if "CreateAction" in as_list(e.get("@type"))]
    # The workflow run first, then the steps by start time
    return sorted(actions, key=lambda a: (a["@id"] != "#workflow-run", a.get("startTime", "")))


def _software(action: dict, entities: dict[str, dict]) -> str:
    instrument = entities.get(action.get("instrument", {}).get("@id"), {})
    names = []
    for software in [instrument] + [entities.get(r["@id"], {}) for r in as_list(instrument.get("softwareRequirements"))]:
        version = software.get("softwareVersion") or software.get("version")
        if software.get("name"):
            names.append(f"{software['name']} {version}" if version else software["name"])
    return ", ".join(names)


def _value(value: Any, entities: dict[str, dict]) -> str:
    """Return a property value as HTML, references to entities of the crate as links."""
    if isinstance(value, list):
        return "<br>".join(_value(v, entities) for v in value)
    if isinstance(value, dict) and "@id" in value:
        entity_id = value["@id"]
        label = escape(str(entities.get(entity_id, {}).get("name", entity_id)))
        if entity_id in entities:
            return f'<a href="#{_anchor(entity_id)}">{label}</a>'
        if entity_id.startswith(("http://", "https://")):
            return f'<a href="{escape(entity_id)}">{label}</a>'
        return f'<span class="id">{label}</span>'
    if isinstance(value, dict):
        return f"<code>{escape(json.dumps(value))}</code>"
    return escape(str(value))


def _anchor(entity_id: str) -> str:
    return "entity-" + hashlib.sha1(entity_id.encode()).hexdigest()[:12]
